<?php require 'config.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='job'){if(trim($_POST['title']??'')&&trim($_POST['company']??'')&&trim($_POST['description']??'')){$q=$pdo->prepare('INSERT INTO jobs(title,company,description,eligibility,location,deadline,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([trim($_POST['title']),trim($_POST['company']),trim($_POST['description']),trim($_POST['eligibility']??''),trim($_POST['location']??''),($_POST['deadline']??'')?:null,$_SESSION['user_id']]);$msg='Job published.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='status'){$q=$pdo->prepare("UPDATE applications SET status=? WHERE id=?");$allowed=['Under Review','Shortlisted','Rejected','Selected'];if(in_array($_POST['status']??'',$allowed,true))$q->execute([$_POST['status'],(int)$_POST['application_id']]);}
$jobs=$pdo->query('SELECT * FROM jobs ORDER BY created_at DESC')->fetchAll();$apps=$pdo->query('SELECT a.id,a.status,u.name,u.email,j.title,j.company FROM applications a JOIN users u ON u.id=a.user_id JOIN jobs j ON j.id=a.job_id ORDER BY a.applied_at DESC')->fetchAll();include 'header.php';?>
<h2>Admin Dashboard</h2><?php if($msg):?><div class="alert alert-success"><?=h($msg)?></div><?php endif;?>
<div class="card p-4 mb-4"><h4>Publish a Job</h4><form method="post"><input type="hidden" name="action" value="job"><div class="row g-3"><div class="col-md-6"><label class="form-label">Job title</label><input class="form-control" name="title" required></div><div class="col-md-6"><label class="form-label">Company</label><input class="form-control" name="company" required></div><div class="col-md-6"><label class="form-label">Location</label><input class="form-control" name="location"></div><div class="col-md-6"><label class="form-label">Application deadline</label><input class="form-control" type="date" name="deadline"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" required></textarea></div><div class="col-12"><label class="form-label">Eligibility</label><input class="form-control" name="eligibility" placeholder="e.g. B.Tech, 60% aggregate"></div></div><button class="btn btn-primary mt-3">Publish Job</button></form></div>
<h4>Applications</h4><div class="card p-3 mb-4"><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Email</th><th>Job</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><?=h($a['name'])?></td><td><?=h($a['email'])?></td><td><?=h($a['title'])?> — <?=h($a['company'])?></td><td><?=h($a['status'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="action" value="status"><input type="hidden" name="application_id" value="<?=$a['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['Under Review','Shortlisted','Rejected','Selected'] as $s):?><option <?=($a['status']===$s?'selected':'')?>><?=h($s)?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<h4>Posted Jobs</h4><div class="card p-3"><ul class="mb-0"><?php foreach($jobs as $j):?><li><?=h($j['title'])?> at <?=h($j['company'])?></li><?php endforeach;?></ul></div><?php include 'footer.php';?>